PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS settings(currency TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','supervisor','viewer')));
CREATE TABLE IF NOT EXISTS projects(id INTEGER PRIMARY KEY, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, location TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS crews(id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, contractor TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workers(id INTEGER PRIMARY KEY, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('blue_collar','white_collar','administrative')), trade TEXT NOT NULL, crew INTEGER NOT NULL REFERENCES crews(id), hourly_cents INTEGER NOT NULL CHECK(hourly_cents>=0), overtime_bp INTEGER NOT NULL CHECK(overtime_bp BETWEEN 10000 AND 30000), daily_minutes INTEGER NOT NULL CHECK(daily_minutes BETWEEN 60 AND 1440), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE IF NOT EXISTS activities(id INTEGER PRIMARY KEY, project INTEGER NOT NULL REFERENCES projects(id), code TEXT NOT NULL, name TEXT NOT NULL, trade TEXT NOT NULL, zone TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('direct','indirect')), unit TEXT NOT NULL, target_milli INTEGER NOT NULL CHECK(target_milli>=0), budget_minutes INTEGER NOT NULL CHECK(budget_minutes>0), UNIQUE(project,code));
CREATE TABLE IF NOT EXISTS sheets(id INTEGER PRIMARY KEY, activity INTEGER NOT NULL REFERENCES activities(id), work_date TEXT NOT NULL, output_milli INTEGER NOT NULL CHECK(output_milli>=0), note TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','void')), creator INTEGER NOT NULL REFERENCES users(id), reviewer INTEGER REFERENCES users(id), reviewed_at TEXT, request_key TEXT UNIQUE NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS time_lines(id INTEGER PRIMARY KEY, sheet INTEGER NOT NULL REFERENCES sheets(id), worker INTEGER NOT NULL REFERENCES workers(id), regular_minutes INTEGER NOT NULL CHECK(regular_minutes>=0), overtime_minutes INTEGER NOT NULL CHECK(overtime_minutes>=0), hourly_cents INTEGER NOT NULL, overtime_bp INTEGER NOT NULL, category TEXT NOT NULL, trade TEXT NOT NULL, crew_name TEXT NOT NULL, contractor TEXT NOT NULL, UNIQUE(sheet,worker), CHECK(regular_minutes+overtime_minutes>0));
CREATE INDEX IF NOT EXISTS time_worker ON time_lines(worker,sheet);
CREATE INDEX IF NOT EXISTS sheet_date ON sheets(work_date,status,activity);
CREATE UNIQUE INDEX IF NOT EXISTS one_approved_output ON sheets(activity,work_date) WHERE status='approved';
CREATE TABLE IF NOT EXISTS allocations(id INTEGER PRIMARY KEY, worker INTEGER NOT NULL REFERENCES workers(id), project INTEGER NOT NULL REFERENCES projects(id), work_date TEXT NOT NULL, minutes INTEGER NOT NULL CHECK(minutes>0), UNIQUE(worker,project,work_date));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, actor INTEGER NOT NULL REFERENCES users(id), action TEXT NOT NULL, sheet INTEGER REFERENCES sheets(id), detail TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER IF NOT EXISTS frozen_sheet BEFORE UPDATE ON sheets WHEN OLD.status IN ('approved','void') AND NOT (OLD.status='approved' AND NEW.status='void' AND NEW.id=OLD.id AND NEW.activity=OLD.activity AND NEW.work_date=OLD.work_date AND NEW.output_milli=OLD.output_milli AND NEW.note=OLD.note AND NEW.creator=OLD.creator AND NEW.request_key=OLD.request_key AND NEW.created_at=OLD.created_at AND NEW.reviewer=OLD.reviewer AND NEW.reviewed_at=OLD.reviewed_at) BEGIN SELECT RAISE(ABORT,'Approved sheets are immutable'); END;
CREATE TRIGGER IF NOT EXISTS frozen_delete BEFORE DELETE ON sheets WHEN OLD.status!='draft' BEGIN SELECT RAISE(ABORT,'Submitted sheets cannot be deleted'); END;
CREATE TRIGGER IF NOT EXISTS frozen_line_update BEFORE UPDATE ON time_lines WHEN (SELECT status FROM sheets WHERE id=OLD.sheet)!='draft' BEGIN SELECT RAISE(ABORT,'Submitted time lines are immutable'); END;
CREATE TRIGGER IF NOT EXISTS frozen_line_delete BEFORE DELETE ON time_lines WHEN (SELECT status FROM sheets WHERE id=OLD.sheet)!='draft' BEGIN SELECT RAISE(ABORT,'Submitted time lines are immutable'); END;
CREATE TRIGGER IF NOT EXISTS frozen_line_insert BEFORE INSERT ON time_lines WHEN (SELECT status FROM sheets WHERE id=NEW.sheet)!='draft' BEGIN SELECT RAISE(ABORT,'Submitted time lines are immutable'); END;
